test("RF-006: lo reservado no se vende dos veces", () => {
  const movs = registrarMovimiento(conIngreso(), { tipo: "reserva", articulo: "A1", almacen: "LPZ", cantidad: 6 });
  assert.equal(stock(movs, "A1", "LPZ"), 10);
  assert.equal(reservado(movs, "A1", "LPZ"), 6);
  assert.equal(disponible(movs, "A1", "LPZ"), 4);
  assert.throws(() => registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 5 }), /Stock insuficiente/);
  assert.throws(() => registrarMovimiento(movs, { tipo: "reserva", articulo: "A1", almacen: "LPZ", cantidad: 5 }), /Stock insuficiente/);
  registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 4 });
});

test("RF-006: liberar y despachar una reserva", () => {
  let movs = registrarMovimiento(conIngreso(), { tipo: "reserva", articulo: "A1", almacen: "LPZ", cantidad: 6 });
  assert.throws(() => registrarMovimiento(movs, { tipo: "liberacion", articulo: "A1", almacen: "LPZ", cantidad: 7 }), /Reserva insuficiente/);
  movs = registrarMovimiento(movs, { tipo: "liberacion", articulo: "A1", almacen: "LPZ", cantidad: 6 });
  movs = registrarMovimiento(movs, { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 6 });
  assert.equal(stock(movs, "A1", "LPZ"), 4);
  assert.equal(reservado(movs, "A1", "LPZ"), 0);
});
